89	export interface ResolvedPath {
90	  /** URL path with colon-style path parameters, e.g. `/api/users/:userid`. */
91	  path: string;
92	  /** Insomnia path parameters to store on the request (values pre-filled as empty). */
93	  pathParameters: { name: string; value: string }[];
94	}
