/**
 * Finds the earliest Nunjucks-style opening delimiter (`{{` or `{%`) at or after
 * `from`. Returns its index and which delimiter it is, or `-1` when neither is
 * present.
 */
function findNextOpening(input: string, from: number): { index: number; open: '{{' | '{%' } {
  const variable = input.indexOf('{{', from);
  const tag = input.indexOf('{%', from);
  if (variable === -1 && tag === -1) { return { index: -1, open: '{{' }; }
